1	import { ok, fail } from './result.js';
2	
3	export const RATES = { EUR: 1, USD: 1.085, GBP: 0.8425 };
4	
5	/**
6	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
7	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
8	 * @param {number} x
9	 * @returns {number}
10	 */
11	export function roundCents(x) {
12	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
13	  const floor = Math.floor(r);
14	  const diff = r - floor;
15	  if (diff > 0.5) return floor + 1;
16	  if (diff < 0.5) return floor === 0 ? 0 : floor;
17	  return floor % 2 === 0 ? floor : floor + 1;
18	}
19	
20	/**
21	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
22	 * @param {number} cents
23	 * @returns {string}
24	 */
25	export function formatEuros(cents) {
26	  const sign = cents < 0 ? '-' : '';
27	  const abs = Math.abs(cents);
28	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
29	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
30	}
31	
32	/**
33	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
34	 * @param {string} text
35	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
36	 */
37	export function parseEuros(text) {
38	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
39	  if (!m) return fail('AMOUNT_INVALID');
40	  const euros = Number(m[1].replace(/,/g, ''));
41	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
42	  return ok(euros * 100 + cents);
43	}
44	
45	/**
46	 * Convert cents from EUR to another currency.
47	 * @param {number} cents amount in EUR cents
48	 * @param {string} currency target currency (EUR, USD, GBP)
49	 * @returns {{ ok: true, value: number } | { ok: false, error: string }} amount in target currency's cents
50	 */
51	export function convert(cents, currency) {
52	  if (!(currency in RATES)) {
53	    return fail('UNKNOWN_CURRENCY');
54	  }
55	  const rate = RATES[currency];
56	  const converted = cents * rate;
57	  return ok(roundCents(converted));
58	}
59	
60	/**
61	 * Format cents as money for a specific currency: 123456 USD -> "$1,234.56", -5 GBP -> "-£0.05".
62	 * @param {number} cents
63	 * @param {string} currency EUR, USD, or GBP
64	 * @returns {string}
65	 */
66	export function formatMoney(cents, currency) {
67	  if (!(currency in RATES)) {
68	    return formatEuros(cents);
69	  }
70	
